# generated by tools/ail2py.py from environment_config_main.ail; edit the .ail until onelang s16
from environment_config import *
from json_text import *
from ail import current_dir
import sys

def main() -> int:
    if len(sys.argv) != 1:
        print('usage: environment_config', file=sys.stderr)
        return 2
    try:
        count = env_int('AIL_CONFIG_COUNT', 1)
        enabled = env_bool('AIL_CONFIG_ENABLED', 0)
        directory = current_dir()
        print('{"count":' + str(count) + ',"enabled":' + str(enabled) + ',"directory":' + json_quote(directory) + '}')
        return 0
    except OSError:
        print('configuration access failed', file=sys.stderr)
        return 3
    except ValueError:
        print('invalid configuration', file=sys.stderr)
        return 4
    except UnicodeDecodeError:
        print('configuration is not valid Unicode', file=sys.stderr)
        return 4
    return 0

if __name__ == "__main__":
    sys.exit(main())
